INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(18000338, 'Re: EX', '复王龙EX', 'Re：EX', 'Effect Monster', 'Dinosaur', 'LIGHT', 4, 1900, 1200, '①：这张卡和额外怪兽区域的怪兽进行战斗的场合，只在伤害步骤内这张卡的攻击力·守备力上升800。'),
(91020571, 'Reactan, Dragon Ruler of Pebbles', '地征龙－沉积', '地征竜－リアクタン', 'Effect Monster', 'Dragon', 'EARTH', 4, 1800, 1200, '这个卡名的效果1回合只能使用1次。 ①：把1只龙族或地属性的怪兽和这张卡从手卡丢弃才能发动。从卡组把1只「岩征龙-锈龙」特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(79387392, 'Reactor Slime', '反应机史莱姆', 'リアクター・スライム', 'Effect Monster', 'Aqua', 'WATER', 4, 500, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。在自己场上把2只「史莱姆怪兽衍生物」（水族·水·1星·攻/守500）特殊召唤。这个回合，自己不是幻神兽族怪兽不能召唤·特殊召唤。 ②：自己·对方的战斗阶段把这张卡解放才能发动。从自己的手卡·卡组·墓地选1张「金属反射史莱姆」在自己的魔法与陷阱区域盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(31785398, 'Ready for Intercepting', '迎击准备', '迎撃準備', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上的1只表侧表示存在的战士族或魔法师族怪兽变成里侧守备表示。'),
(63854005, 'Ready Fusion', '简素结合', '簡素融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：支付1000基本分才能发动。除效果怪兽外的1只6星以下的融合怪兽当作融合召唤从额外卡组特殊召唤。这个效果特殊召唤的怪兽不能攻击，结束阶段破坏。'),
(71771004, 'Readying of Rites', '仪式的筹备', NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从卡组把1只恶魔族仪式怪兽加入手卡，把灵摆怪兽加入手卡的场合，可以再在自己场上把1只「牺牲供物衍生物」（恶魔族·暗属性·1星·攻300/守300）特殊召唤。只要这衍生物在自己场上存在，自己不能从额外卡组特殊召唤。 自己的仪式怪兽给与对方战斗伤害时：可以把自己墓地的这张卡除外；自己抽1张。 「仪式的筹备」的每个效果1回合各能使用1次。'),
(28121403, 'Really Eternal Rest', '大成佛', '大成仏', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '破坏场上所有装备了装备卡的怪兽。'),
(17462320, 'Realm Elegy', '世坏挽歌', '世壊挽歌', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从卡组把1只「吠陀」怪兽加入手卡。 ②：这张卡在墓地存在，场上有「维萨斯-斯塔弗罗斯特」存在的状态，自己场上的表侧表示的调整被战斗·效果破坏的场合，把这张卡除外，以那之内的1只为对象才能发动。那只怪兽加入手卡。'),
(54851325, 'Realm Eulogy', '世坏赞歌', '世壊賛歌', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只怪兽和对方场上1只效果怪兽为对象才能发动。那只自己怪兽破坏，那只对方怪兽的效果直到回合结束时无效。那之后，场上有「维萨斯-斯塔弗罗斯特」存在的场合，可以把作为对象的怪兽破坏。 ②：场上有「吠陀」怪兽卡存在的场合，自己主要阶段把墓地的这张卡除外才能发动。自己场上1只怪兽破坏。'),
(79698395, 'Realm of Danger!', '未界域－欧玛利亚大陆', '未界域－ユーマリア大陸', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，自己场上的「未界域」怪兽在特殊召唤的回合不会成为对方的效果的对象。 ②：1回合1次，以自己场上1只「未界域」怪兽为对象才能发动。只要那只怪兽和这张卡在自己场上表侧表示存在，那只怪兽可以直接攻击，不会被作为攻击对象（自己场上只有被这个效果适用的怪兽存在的状态中对方的攻击变成对自己的直接攻击）。'),
(36099620, 'Realm of Light', '正义世界', 'ジャスティス・ワールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '每次从自己卡组有卡被送去墓地，给这张卡放置1个光指示物。每有1个光指示物，场上名字带有「光道」的怪兽的攻击力上升100。场上表侧表示存在的这张卡被其他的卡的效果破坏的场合，作为代替把2个光指示物取除。'),
(36920182, 'Realm Resonance', '世坏同心', '世壊同心', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●从自己墓地把1只攻击力1500/守备力2100的怪兽特殊召唤。 ●自己的场上（表侧表示）·墓地·除外状态的1只「维萨斯-斯塔弗罗斯特」和4只攻击力1500/守备力2100的怪兽回到卡组，把1只「维萨斯」同调怪兽当作同调召唤从额外卡组特殊召唤。'),
(60312997, 'Reanimation Wave', '波动再生', '波動再生', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的直接攻击宣言时，从自己墓地选择持有那只攻击怪兽的等级以下的等级的1只同调怪兽发动。那个时候的攻击发生的对自己的战斗伤害变成一半数值。那次伤害步骤结束时，选择的同调怪兽从自己墓地特殊召唤。'),
(9560338, 'Reaper of Prophecy', '魔导冥士 拉莫尔', '魔導冥士 ラモール', 'Effect Monster', 'Spellcaster', 'DARK', 6, 2000, 1600, '这张卡召唤·特殊召唤成功时才能发动。自己墓地的名字带有「魔导书」的魔法卡种类的以下效果适用。「魔导冥士 拉莫尔」的效果1回合只能使用1次。 ●3种类以上：这张卡的攻击力上升600。 ●4种类以上：从卡组把1张名字带有「魔导书」的魔法卡加入手卡。 ●5种类以上：从卡组把1只魔法师族·暗属性·5星以上的怪兽特殊召唤。'),
(33066139, 'Reaper of the Cards', '猎卡死神', 'カードを狩る死神', 'Flip Effect Monster', 'Fiend', 'DARK', 5, 1380, 1930, '反转：选择场上存在的1张陷阱卡破坏。选择的卡是盖放的场合，把那张卡翻开确认，是陷阱卡则破坏。魔法卡的场合回到原状。'),
(85684223, 'Reaper on the Nightmare', '驱使梦魇的死灵', 'ナイトメアを駆る死霊', 'Fusion Monster', 'Zombie', 'DARK', 5, 800, 600, '「削魂的死灵」＋「梦魇马」 这张卡不会被战斗破坏。这张卡成为魔法·陷阱·效果怪兽效果的对象时，这张卡破坏。这张卡在对方场上存在怪兽的状态下也能对对方进行直接攻击。这张卡对对方进行直接攻击成功时，对方随机丢弃1张手卡。'),
(81954378, 'Reaper Scythe - Dreadscythe', '死神的大镰-断魂', '死神の大鎌－デスサイス', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「守护者·戴思塞斯」才能装备。 ①：装备怪兽的攻击力上升双方墓地的怪兽数量×500。'),
(58577036, 'Reasoning', '名推理', '名推理', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方宣言1～12的任意等级。直到可以通常召唤的怪兽出现为止从自己卡组上面翻卡，那只怪兽的等级和宣言的等级相同的场合，翻开的卡全部送去墓地。不是的场合，那只怪兽特殊召唤，剩下的翻开的卡全部送去墓地。'),
(87567063, 'Rebellion', '造反剧', '造反劇', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的战斗阶段以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到战斗阶段结束时得到。这个回合，作为对象的怪兽以外的自己怪兽不能攻击。'),
(45064756, 'Rebirth Judgment', '轮回独断', '輪廻独断', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，宣言1个种族才能发动。这个回合，双方墓地的怪兽变成宣言的种族。'),
(23459650, 'Rebirth of Nephthys', '奈芙蒂斯的轮回', 'ネフティスの輪廻', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「奈芙提斯」仪式怪兽的降临必需。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「奈芙提斯」仪式怪兽仪式召唤。把「奈芙提斯之祭祀者」或者「奈芙提斯之苍凰神」解放作仪式召唤的场合，可以再选场上1张卡破坏。'),
(42444868, 'Rebirth of Parshath', '轮回之珀耳修斯', '輪廻のパーシアス', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：怪兽的效果·魔法·陷阱卡发动时，把手卡1张反击陷阱卡给对方观看，丢弃1张手卡，支付1000基本分才能发动。那个发动无效，那张卡回到持有者卡组。那之后，可以从卡组·额外卡组选1只「珀耳修斯」怪兽特殊召唤。'),
(83888009, 'Rebirth of the Seventh Emperors', '七皇再生', '七皇再生', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上的超量怪兽全部解放，以除外的1只自己的超量怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以从自己墓地的怪兽以及除外的自己怪兽之中选最多有解放的怪兽数量＋1只的「No.101」～「No.107」其中任意种的「No.」超量怪兽在那只特殊召唤的怪兽下面重叠作为超量素材。这张卡发动的回合的结束阶段，双方各自受到自身手卡数量×300伤害。'),
(85775486, 'Reboot', '再机动', '再機動', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己手卡让1只名字带有「机皇」的怪兽回到卡组发动。选择自己墓地存在的1张名字带有「机皇」的卡加入手卡。'),
(10028593, 'Reborn Tengu', '轮回天狗', '輪廻天狗', 'Effect Monster', 'Beast-Warrior', 'WIND', 4, 1700, 600, '①：表侧表示的这张卡从场上离开的场合发动。从卡组把1只「轮回天狗」特殊召唤。'),
(23421244, 'Reborn Zombie', '再生僵尸', 'リボーン・ゾンビ', 'Effect Monster', 'Zombie', 'DARK', 4, 1000, 1600, '只要自己手卡是0张，场上攻击表示存在的这张卡不会被战斗破坏。'),
(983995, 'Rebound', '篮板球', 'リ・バウンド', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '要让场上的卡回到手卡的效果由对方发动时才能发动。那个效果无效，从对方的手卡·场上选1张卡送去墓地。此外，盖放的这张卡被对方破坏送去墓地时，从卡组抽1张卡。'),
(4550066, 'Rebuildeer', '重建鹿', 'リビルディア', 'Effect Monster', 'Cyberse', 'WIND', 4, 1800, 800, '①：这张卡战斗破坏对方怪兽时，以自己墓地1只攻击力1500以下的电子界族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(96404912, 'Recall', '无偿交换', '無償交換', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：对方把怪兽的效果发动时才能发动。那个发动无效并破坏。对方从卡组抽1张。'),
(73271204, 'Recardination', '札再生', '札再生', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「花札卫」怪兽为对象才能发动。那只怪兽加入手卡。那之后，可以从手卡把1只「花札卫」怪兽无视召唤条件特殊召唤。 ②：这张卡被「花札卫」怪兽的效果送去墓地的场合才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1张魔法·陷阱卡加入手卡。剩下的卡用喜欢的顺序回到卡组上面。'),
(40551410, 'Recette de Personnel (Staff Recipe)', 'Recette de Personnel～伙食食谱～', 'Recette de Personnel～賄いのレシピ～', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只仪式怪兽为对象才能发动。在自己场上把1只「新式魔厨衍生物」（恶魔族·暗·1星·攻/守50）特殊召唤。这衍生物的等级变成和作为对象的怪兽相同。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放，从手卡把1只「新式魔厨」仪式怪兽仪式召唤。'),
(87778106, 'Recette de Poisson (Fish Recipe)', 'Recette de Poisson～鱼料理食谱～', 'Recette de Poisson～魚料理のレシピ～', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「新式魔厨」仪式怪兽的降临必需。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「新式魔厨」仪式怪兽仪式召唤。这个效果把「新式魔厨的马赛鱼汤布耶尔」仪式召唤的场合，可以再让以下效果适用。 ●从自己的卡组·墓地把「鱼料理的食谱」以外的1张「食谱」仪式魔法卡加入手卡。'),
(14166715, 'Recette de Viande (Meat Recipe)', 'Recette de Viande～肉料理食谱～', 'Recette de Viande～肉料理のレシピ～', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「新式魔厨」仪式怪兽的降临必需。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「新式魔厨」仪式怪兽仪式召唤。这个效果把「新式魔厨的油封佛拉斯」仪式召唤的场合，可以再让以下效果适用。 ●对方场上的守备表示怪兽全部变成表侧攻击表示。'),
(37576645, 'Reckless Greed', '无谋的贪欲', '無謀な欲張り', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己从卡组抽2张，那之后的自己抽卡阶段跳过2次。'),
(11596936, 'Reckoned Power', '失控能量', 'レクリスパワー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把手卡1张「核成兽的钢核」给对方观看发动。对方场上盖放的魔法·陷阱卡全部破坏。'),
(70238111, 'Recoded Alive', '重编码存活', 'リコーデッド・アライブ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己的场上·墓地1只连接3电子界族连接怪兽为对象才能发动。那只怪兽除外，从额外卡组把1只「码语者」怪兽特殊召唤。 ②：额外怪兽区域没有自己怪兽存在的场合，把墓地的这张卡除外，以除外的1只自己的「码语者」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(31467949, 'Recon, Scout Fur Hire', '空牙团的飞哨 莉空', '空牙団の飛哨 リコン', 'Effect Monster', 'Beast', 'WIND', 2, 1000, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把「空牙团的飞哨 锐康」以外的1只「空牙团」怪兽特殊召唤。 ②：这张卡已在怪兽区域存在的状态，自己场上有这张卡以外的「空牙团」怪兽特殊召唤的场合，以场上盖放的1张卡为对象才能发动。那张卡破坏。'),
(76232522, 'Recovery Sorcerer', '恢复巫师', 'リカバリー・ソーサラー', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1500, NULL, '电子界族怪兽2只 这个卡名的效果1回合只能使用1次。 ①：以这个回合被破坏的自己墓地1只电子界族连接怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。这个效果在对方回合也能发动。'),
(81191584, 'Recurring Nightmare', '噩梦再临', '悪夢再び', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地2只守备力0的暗属性怪兽为对象才能发动。那些暗属性怪兽加入手卡。'),
(96316857, 'Recycle', '再生', 'リサイクル', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '在自己准备阶段支付300基本分，就可从存在于自己墓地的卡里选择1张怪兽卡以外的卡放回卡组最下方。'),
(99995595, 'Recycling Batteries', '电池回收', 'バッテリーリサイクル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地2只攻击力1500以下的雷族怪兽为对象才能发动。那些雷族怪兽加入手卡。'),
(65570596, 'Red Archery Girl', '拉弓的人鱼', '弓を引くマーメイド', 'Normal Monster', 'Aqua', 'WATER', 4, 1400, 1500, '平常躲在贝壳里，对擅自接近的人射箭的美人鱼。'),
(844056, 'Red Arrows', '红箭', 'レッドアローズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以额外怪兽区域最多2只表侧表示怪兽为对象才能发动。那些怪兽直到结束阶段除外。'),
(71521025, 'Red Blossoms from Underroot', '幽世血樱', 'カクリヨノチザクラ', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，从自己以及对方的墓地各以1张魔法·陷阱卡为对象才能发动。那些卡除外，这张卡特殊召唤。 ②：把这张卡解放，以自己或者对方的墓地1只融合·同调·超量·连接怪兽为对象才能发动。那只怪兽除外，从自己墓地选和那只怪兽种类（融合·同调·超量·连接）不同的1只怪兽特殊召唤。'),
(41197012, 'Red Carpet', '真红莲地毯', 'スカーレッド・カーペット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上有龙族同调怪兽存在的场合，以自己墓地最多2只「共鸣者」怪兽为对象才能发动。那些怪兽特殊召唤。'),
(2542230, 'Red Cocoon', '真红莲之茧', 'スカーレッド・コクーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只龙族同调怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。 ②：用这张卡的效果把这张卡装备的怪兽和对方怪兽进行战斗的场合，直到那次伤害步骤结束时对方场上的全部表侧表示怪兽的效果无效化。 ③：这张卡被送去墓地的回合的结束阶段，以自己墓地1只「红莲魔龙」为对象才能发动。那只怪兽特殊召唤。'),
(70902743, 'Red Dragon Archfiend', '暗红恶魔龙', 'レッド・デーモンズ・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 8, 3000, 2000, '调整＋调整以外的怪兽1只以上 ①：这张卡向对方的守备表示怪兽进行攻击的伤害计算后发动。对方场上的守备表示怪兽全部破坏。 ②：自己结束阶段发动。这张卡在场上表侧表示存在的场合，这个回合没有攻击宣言的自己场上的其他怪兽全部破坏。'),
(77336644, 'Red Dragon Archfiend/Assault Mode', '暗红恶魔龙／爆裂', 'レッド・デーモンズ・ドラゴン／バスター', 'Effect Monster', 'Dragon', 'DARK', 10, 3500, 2500, '这张卡不能通常召唤，用「爆裂模式」的效果才能特殊召唤。 ①：这张卡攻击的伤害计算后发动。场上的其他怪兽全部破坏。 ②：场上的这张卡被破坏时，以自己墓地1只「红莲魔龙」为对象才能发动。那只怪兽特殊召唤。'),
(58165765, 'Red Dragon Ninja', '红龙忍者', '赤竜の忍者', 'Effect Monster', 'Winged Beast', 'FIRE', 6, 2400, 1200, '这张卡召唤·反转召唤·特殊召唤成功时，把自己墓地1张名字带有「忍者」或者「忍法」的卡从游戏中除外，选择对方场上盖放的1张卡才能发动。把选择的卡确认，回到持有者卡组最上面或者最下面。对方不能对应这个效果的发动把选择的卡发动。「红龙忍者」的效果1回合只能使用1次。'),
(87614611, 'Red Dragon Vase', '红莲魔龙之壶', '紅蓮魔竜の壺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有「红莲魔龙」表侧表示存在的场合才能发动。从自己卡组抽2张卡。这张卡发动的场合，直到下次的对方回合结束时自己不能把怪兽召唤·特殊召唤。'),
(61019812, 'Red Duston', '红尘妖', 'レッド・ダストン', 'Effect Monster', 'Fiend', 'FIRE', 1, NULL, 1000, '这张卡不能解放，也不能作为融合·同调·超量召唤的素材。场上的这张卡被破坏时，这张卡的控制者受到500分伤害。「红尘妖」在自己场上只能有1只表侧表示存在。'),
(8372133, 'Red Familiar', '绯暗红使魔', 'スカーレッド・ファミリア', 'Effect Monster', 'Fiend', 'DARK', 4, 1600, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只恶魔族怪兽解放，以自己墓地1只龙族·暗属性同调怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：把墓地的这张卡除外，以自己场上1只龙族·暗属性同调怪兽为对象，宣言1～8的任意等级才能发动。那只怪兽直到回合结束时变成宣言的等级。'),
(86445415, 'Red Gadget', '红色小工具', 'レッド・ガジェット', 'Effect Monster', 'Machine', 'EARTH', 4, 1300, 1500, '①：这张卡召唤·特殊召唤成功时才能发动。从卡组把1只「黄色零件」加入手卡。'),
(72318602, 'Red Gardna', '红莲守卫者', 'レッド・ガードナー', 'Effect Monster', 'Fiend', 'FIRE', 4, NULL, 2000, '①：自己场上有「红莲魔」怪兽存在，对方的魔法·陷阱·怪兽的效果发动时，把这张卡从手卡送去墓地才能发动。这个回合，自己场上的怪兽不会被对方的效果破坏。'),
(19636995, 'Red Hared Hasty Horse', '急兔马', '急き兎馬', 'Effect Monster', 'Beast', 'WIND', 5, 2000, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：有着没有卡存在的纵列的场合，这张卡可以从手卡往那个纵列的自己场上攻击表示特殊召唤。 ②：和这张卡相同纵列有其他卡被放置的场合发动。这张卡破坏。 ③：1回合1次，自己主要阶段才能发动。这个回合，这张卡的原本攻击力变成一半，可以直接攻击。'),
(30698243, 'Red Hypernova Dragon', NULL, NULL, 'Synchro Monster', 'Dragon', 'DARK', 12, 4500, 3000, NULL),
(19299793, 'Red Lotus King, Flame Crime', '红莲王 炎罪', '紅蓮王 フレイム・クライム', 'Effect Monster', 'Fiend', 'FIRE', 3, 1700, 300, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己场上有恶魔族调整存在的场合或者对方场上有特殊召唤的怪兽存在的场合，自己·对方的主要阶段才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。给与对方为自己场上的炎属性怪兽种类×400伤害。 ③：这张卡作为同调素材送去墓地的场合才能发动。从卡组把1张通常陷阱卡送去墓地。'),
(38199696, 'Red Medicine', '红色药剂', 'レッド・ポーション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己的基本分回复500。'),
(8706701, 'Red Mirror', '红莲镜', 'レッド・ミラー', 'Effect Monster', 'Fiend', 'FIRE', 1, NULL, NULL, '「红莲镜」的①②的效果1回合各能使用1次。 ①：对方怪兽的攻击宣言时，把这张卡从手卡送去墓地，以「红莲镜」以外的自己墓地1只恶魔族·炎属性怪兽为对象才能发动。那只怪兽加入手卡。 ②：这张卡在墓地存在，自己同调召唤成功的场合才能发动。墓地的这张卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(21142671, 'Red Nova', '暗红新星', 'レッド・ノヴァ', 'Tuner Monster', 'Fairy', 'FIRE', 1, NULL, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：场上有8星以上的龙族同调怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：调整2只以上为素材的同调召唤让这张卡作为同调素材送去墓地的场合才能发动。从卡组把1只恶魔族·炎属性怪兽守备表示特殊召唤。'),
(97489701, 'Red Nova Dragon', '绯暗红新星龙', 'スカーレッド・ノヴァ・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 12, 3500, 3000, '调整2只＋「红莲魔龙」 ①：这张卡的攻击力上升自己墓地的调整数量×500。 ②：场上的这张卡不会被对方的效果破坏。 ③：对方怪兽的攻击宣言时，以那1只攻击怪兽为对象才能发动。场上的这张卡除外，那次攻击无效。 ④：这张卡的③的效果除外的回合的结束阶段发动。这张卡特殊召唤。'),
(82323997, 'Red Nova Dragon/Assault Mode', NULL, NULL, 'Effect Monster', 'Dragon', 'DARK', 12, 4000, 3500, NULL),
(68722455, 'Red Ogre', '赤鬼', '赤鬼', 'Effect Monster', 'Zombie', 'EARTH', 7, 2800, 2100, '这张卡召唤成功时，可以把自己手卡任意数量送去墓地，那个数量的场上的卡回到持有者手卡。'),
(16001119, 'Red Potan', '红面波波', 'レッドポータン', 'Effect Monster', 'Fairy', 'FIRE', 1, 100, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「波波」怪兽为对象才能发动。那只怪兽直到下个回合的结束时当作调整使用。 ②：这张卡已在怪兽区域存在的状态，自己或者对方同调召唤成功的场合才能发动。从手卡·卡组把1只「波波」怪兽特殊召唤。'),
(23002292, 'Red Reboot', '红灯重启', 'レッド・リブート', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这张卡也能把基本分支付一半从手卡发动。 ①：对方把陷阱卡发动时才能发动。那个发动无效，那张卡直接盖放。那之后，对方可以从卡组把1张陷阱卡在自身的魔法与陷阱区域盖放。这张卡的发动后，直到回合结束时对方不能把陷阱卡发动。'),
(5376159, 'Red Reign', '绯暗红陨雨', 'スカーレッド・レイン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上有8星以上的同调怪兽存在的场合才能发动。场上的怪兽之内除等级最高的怪兽以外的怪兽全部除外。场上的全部表侧表示怪兽直到回合结束时不受自身以外的卡的效果影响。 ②：这张卡在墓地存在的状态，自己场上有龙族·暗属性同调怪兽同调召唤的场合才能发动。这张卡加入手卡。'),
(40975574, 'Red Resonator', '红莲共鸣者', 'レッド・リゾネーター', 'Tuner Monster', 'Fiend', 'FIRE', 2, 600, 200, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤时才能发动。从手卡把1只4星以下的怪兽特殊召唤。 ②：这张卡特殊召唤时，以场上1只表侧表示怪兽为对象才能发动。自己基本分回复那只怪兽的攻击力的数值。'),
(66141736, 'Red Rising Dragon', '暗红升龙', 'レッド・ライジング・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 6, 2100, 1600, '恶魔族调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤时，以自己墓地1只「共鸣者」怪兽为对象才能发动（这个效果发动的回合，自己不是龙族·暗属性同调怪兽不能从额外卡组特殊召唤）。那只怪兽特殊召唤。 ②：把这个回合没有送去墓地的这张卡从墓地除外，以自己墓地2只1星「共鸣者」怪兽为对象才能发动。那2只怪兽特殊召唤。'),
(26118970, 'Red Rose Dragon', '红蔷薇龙', 'レッドローズ・ドラゴン', 'Tuner Monster', 'Dragon', 'DARK', 3, 1000, 1800, '这个卡名的效果1回合只能使用1次。 ①：这张卡作为同调素材送去墓地的场合才能发动。从手卡·卡组把「赤蔷薇龙」以外的1只「蔷薇龙」怪兽特殊召唤。这张卡作为「黑蔷薇龙」或植物族同调怪兽的同调素材送去墓地的场合，可以再从卡组把1张「冷蔷薇的抱香」或「漆黑之蔷薇的开华」加入手卡。'),
(18634367, 'Red Screen', '红莲屏障', 'スクリーン・オブ・レッド', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的控制者在每次自己结束阶段支付1000基本分。不能支付1000基本分的场合这张卡破坏。 ①：只要这张卡在魔法与陷阱区域存在，对方怪兽不能攻击宣言。 ②：以自己墓地1只1星调整为对象才能发动。这张卡破坏，那只怪兽特殊召唤。这个效果在场上有「红莲魔龙」存在的场合才能发动和处理。'),
(81354330, 'Red Sparrow Summoner', '朱雀召唤士', '朱雀の召喚士', 'Effect Monster', 'Spellcaster', 'FIRE', 4, 1600, 1300, '①：这张卡被对方怪兽的攻击破坏送去墓地时才能发动。从卡组把1只攻击力1500以下的战士族怪兽攻击表示特殊召唤。'),
(14886469, 'Red Sprinter', '红莲赛马', 'レッド・スプリンター', 'Effect Monster', 'Fiend', 'FIRE', 4, 1700, 1200, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤时，若自己场上没有其他怪兽存在则能发动。从自己的手卡·墓地把1只3星以下的恶魔族调整特殊召唤。'),
(99585850, 'Red Supernova Dragon', '绯暗红超新星龙', 'スカーレッド・スーパーノヴァ・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 12, 4000, 3000, '调整3只＋调整以外的同调怪兽1只以上 这张卡用同调召唤才能从额外卡组特殊召唤。 ①：这张卡的攻击力上升自己墓地的调整数量×500。 ②：场上的这张卡不会被对方的效果破坏。 ③：1回合1次，对方怪兽的效果发动时或者对方怪兽的攻击宣言时才能发动。这张卡以及对方场上的卡全部除外。 ④：这张卡的③的效果除外的场合，下次的自己结束阶段发动。除外状态的这张卡特殊召唤。'),
(50584941, 'Red Supremacy', '红莲霸权', 'レッド・スプレマシー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己墓地1只「红莲魔」同调怪兽除外，以自己场上1只「红莲魔」同调怪兽为对象才能发动。那只怪兽当作和为这张卡发动而除外的「红莲魔」同调怪兽同名卡使用，变成相同效果。'),
(45313993, 'Red Warg', '红莲狼', 'レッド・ウルフ', 'Effect Monster', 'Fiend', 'FIRE', 6, 1400, 2200, '①：自己把「共鸣者」怪兽召唤时才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡的攻击力变成一半。'),
(76547525, 'Red Wyvern', '红莲翼龙', 'レッド・ワイバーン', 'Synchro Monster', 'Dragon', 'FIRE', 6, 2400, 2000, '调整＋调整以外的怪兽1只以上 ①：只在同调召唤的这张卡表侧表示存在才有1次，自己·对方回合，持有比这张卡高的攻击力的怪兽在场上存在的场合才能发动。场上1只攻击力最高的怪兽破坏。'),
(50056656, 'Red Zone', '绯暗红区域', 'スカーレッド・ゾーン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有着「红莲魔龙」或者有那个卡名记述的同调怪兽存在，对方把卡的效果发动时，以场上1张卡为对象才能发动。那张卡破坏。 ②：以自己的除外状态的1只龙族·暗属性同调怪兽为对象才能发动。那只怪兽特殊召唤。'),
(18491580, 'Red-Eyes Alternative Black Dragon', '真红眼亚黑龙', '真紅眼の亜黒竜', 'Effect Monster', 'Dragon', 'DARK', 7, 2400, 2000, '这张卡不能通常召唤。从自己的手卡·场上把1只「真红眼」怪兽解放的场合可以特殊召唤。这个方法的「真红眼亚黑龙」的特殊召唤1回合只能有1次。 ①：这张卡被战斗或者对方的效果破坏的场合，以「真红眼亚黑龙」以外的自己墓地1只7星以下的「真红眼」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽是「真红眼黑龙」的场合，那个原本攻击力变成2倍。'),
(39357122, 'Red-Eyes Archfiend of Lightning', '真红眼凶雷皇－邪性恶魔', '真紅眼の凶雷皇－エビル・デーモン', 'Gemini Monster', 'Fiend', 'DARK', 6, 2500, 1200, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●1回合1次，自己主要阶段才能发动。持有比这张卡的攻击力低的守备力的对方场上的表侧表示怪兽全部破坏。'),
(58257569, 'Red-Eyes Baby Dragon', '真红眼幼龙', '真紅眼の幼竜', 'Effect Monster', 'Dragon', 'DARK', 3, 1200, 700, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只7星以下的「真红眼」怪兽特殊召唤，墓地的这张卡当作攻击力上升300的装备卡使用给那只怪兽装备。 ②：给怪兽装备的这张卡被送去墓地的场合才能发动。从自己的卡组·墓地选1只龙族·1星怪兽加入手卡。'),
(74677422, 'Red-Eyes Black Dragon', '真红眼黑龙', '真紅眼の黒竜', 'Normal Monster', 'Dragon', 'DARK', 7, 2400, 2000, '拥有真红之眼的黑龙。愤怒的黑炎会把映入其眼者全部烧成灰烬。'),
(19747827, 'Red-Eyes Black Dragon Sword', '真红眼黑龙剑', '真紅眼の黒竜剣', 'Fusion Monster', 'Dragon', 'DARK', 7, 2400, 2000, '这张卡在用「赫谟之爪」的效果把自己的手卡·场上的龙族怪兽送去墓地的场合才能特殊召唤。 ①：这张卡特殊召唤成功的场合，以这张卡以外的场上1只怪兽为对象发动。这张卡当作攻击力上升1000的装备卡使用给那只怪兽装备。 ②：用这张卡的效果把这张卡装备的怪兽的攻击力·守备力上升双方的场上·墓地的龙族怪兽数量×500。'),
(30079770, 'Red-Eyes Black Flare Dragon', '真红眼黑炎龙', '真紅眼の黒炎竜', 'Gemini Monster', 'Dragon', 'DARK', 7, 2400, 2000, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡进行战斗的战斗阶段结束时才能发动。给与对方这张卡的原本攻击力数值的伤害。「真红眼黑炎龙」的这个效果1回合只能使用1次。'),
(80870883, 'Red-Eyes Black Fullmetal Dragon', '真红眼黑全钢龙', 'レッドアイズ・ブラックフルメタルドラゴン', 'Effect Monster', 'Machine', 'DARK', 8, 3400, 2400, '这张卡不能通常召唤，用把5星以上的龙族怪兽解放发动的「金属化·强化反射装甲」的效果可以特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从卡组把1张「金属化」陷阱卡在自己场上盖放，这张卡回到卡组。 ②：对方把效果发动时才能发动。那个发动无效。那之后，可以给与对方为对方场上1只攻击表示怪兽的原本攻击力数值的伤害。'),
(64335805, 'Red-Eyes Black Metal Dragon', '真红眼黑钢龙', 'レッドアイズ・ブラックメタルドラゴン', 'Effect Monster', 'Machine', 'DARK', 8, 2800, 2400, NULL),
(27657173, 'Red-Eyes Black Meteor Dragon', '真红眼黑星龙', '真紅眼の黒星竜', 'Effect Monster', 'Dragon', 'DARK', 6, 2000, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡·卡组把1只5星以上的通常怪兽送去墓地才能发动。这张卡从手卡特殊召唤。那之后，这张卡的等级上升1星。 ②：把这个回合没有送去墓地的这张卡从墓地除外才能发动。从自己的卡组·墓地把1张「真红眼融合」加入手卡。'),
(71782404, 'Red-Eyes Burn', '真红眼烧灭', 'レッドアイズ・バーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「真红眼烧灭」在1回合只能发动1张。 ①：自己场上的表侧表示的「真红眼」怪兽被战斗·效果破坏的场合，以破坏的那1只怪兽为对象才能发动。双方玩家受到那只怪兽的原本攻击力数值的伤害。'),
(37818794, 'Red-Eyes Dark Dragoon', '超魔导龙骑士－真红眼龙骑兵', '超魔導竜騎士－ドラグーン・オブ・レッドアイズ', 'Fusion Monster', 'Spellcaster', 'DARK', 8, 3000, 2500, '「黑魔术师」＋「真红眼黑龙」或者龙族效果怪兽 ①：这张卡不会被效果破坏，双方不能把这张卡作为效果的对象。 ②：自己主要阶段才能发动（这个效果在1回合中可以使用最多有作为这张卡的融合素材的通常怪兽数量的次数）。对方场上1只怪兽破坏，给与对方那个原本攻击力数值的伤害。 ③：1回合1次，卡的效果发动时，丢弃1张手卡才能发动。那个发动无效并破坏，这张卡的攻击力上升1000。'),
(96561011, 'Red-Eyes Darkness Dragon', '真红眼暗龙', '真紅眼の闇竜', 'Effect Monster', 'Dragon', 'DARK', 9, 2400, 2000, '这张卡不能通常召唤。把自己场上存在的1只「真红眼黑龙」解放的场合才能特殊召唤。这张卡的攻击力，自己墓地存在的龙族怪兽每有1只上升300。'),
(88264978, 'Red-Eyes Darkness Metal Dragon', '真红眼暗铁龙', 'レッドアイズ・ダークネスメタルドラゴン', 'Effect Monster', 'Dragon', 'DARK', 10, 2800, 2400, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把自己场上1只表侧表示的龙族怪兽除外，从手卡特殊召唤。 ②：自己主要阶段才能发动。从自己的手卡·墓地把「真红眼暗钢龙」以外的1只龙族怪兽特殊召唤。'),
(57135971, 'Red-Eyes Fang with Chain', '带锁链的真红眼牙', '鎖付き真紅眼牙', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「真红眼」怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。装备怪兽在同1次的战斗阶段中最多2次可以向怪兽攻击。 ②：把装备的这张卡送去墓地，以场上1只效果怪兽为对象才能发动。那只效果怪兽当作装备卡使用给这张卡装备过的怪兽装备。只要这个效果把怪兽装备中，装备怪兽变成和那只怪兽相同的攻击力·守备力。'),
(44405066, 'Red-Eyes Flare Metal Dragon', '真红眼钢炎龙', '真紅眼の鋼炎竜', 'XYZ Monster', 'Dragon', 'DARK', 7, 2800, 2400, '7星怪兽×2 ①：持有超量素材的这张卡不会被效果破坏。 ②：只要持有超量素材的这张卡在怪兽区域存在，每次对方把魔法·陷阱·怪兽的效果发动给与对方500伤害。 ③：1回合1次，把这张卡1个超量素材取除，以自己墓地1只「真红眼」通常怪兽为对象才能发动。那只怪兽特殊召唤。这个效果在对方回合也能发动。'),
(6172122, 'Red-Eyes Fusion', '真红眼结合', '真紅眼融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能用这张卡的效果以外把怪兽召唤·特殊召唤。 ①：自己的手卡·卡组·场上的怪兽作为融合素材，把以「真红眼」怪兽为融合素材的1只融合怪兽融合召唤。这个效果特殊召唤的怪兽的卡名当作「真红眼黑龙」使用。'),
(92353449, 'Red-Eyes Insight', '真红眼洞悉', 'レッドアイズ・インサイト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡·卡组把1只「真红眼」怪兽送去墓地才能发动。从卡组把「真红眼看破」以外的1张「真红眼」魔法·陷阱卡加入手卡。'),
(83711531, 'Red-Eyes Metal Claws Dragon', '真红眼钢爪龙', '真紅眼の鋼爪竜', 'Effect Monster', 'Dragon', 'DARK', 7, 2400, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1张里侧表示卡送去墓地才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，若自己的场上或墓地有「金属化·强化反射装甲」存在则能发动。从自己的卡组·墓地把1张「金属化」陷阱卡加入手卡。 ③：只要这张卡在怪兽区域存在，自己让「金属化」陷阱卡在盖放的回合也能发动。'),
(53485634, 'Red-Eyes Retro Dragon', '真红眼溯刻龙', '真紅眼の遡刻竜', 'Effect Monster', 'Dragon', 'DARK', 4, 1700, 1600, '①：自己场上的7星以下的「真红眼」怪兽被对方怪兽的攻击或者对方的效果破坏送去自己墓地的场合才能发动。这张卡从手卡守备表示特殊召唤，尽可能把那些破坏的怪兽以和破坏时相同表示形式特殊召唤。 ②：把这张卡解放才能发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「真红眼」怪兽召唤。'),
(21140872, 'Red-Eyes Slash Dragon', '真红眼黑刃龙', '真紅眼の黒刃竜', 'Fusion Monster', 'Dragon', 'DARK', 7, 2800, 2400, '「真红眼黑龙」＋战士族怪兽 ①：「真红眼」怪兽的攻击宣言时以自己墓地1只战士族怪兽为对象才能发动。那只怪兽当作攻击力上升200的装备卡使用给这张卡装备。 ②：自己场上的卡为对象的卡的效果发动时，把自己场上1张装备卡送去墓地才能发动。那个发动无效并破坏。 ③：这张卡被战斗·效果破坏的场合才能发动。给这张卡装备的怪兽从自己墓地尽可能特殊召唤。'),
(6556909, 'Red-Eyes Soul', '真红眼之魂', '真紅き魂', 'Effect Monster', 'Dragon', 'DARK', 7, 900, 2000, '这个卡名的②的效果1回合只能使用1次，③的效果在决斗中只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「真红眼黑龙」使用。 ②：对方把怪兽特殊召唤的场合，把手卡·场上的这张卡送去墓地才能发动。从手卡·卡组把「真红之魂」以外的1只「真红眼」怪兽特殊召唤。 ③：自己·对方回合，以自己场上1只「真红眼黑龙」为对象才能发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(44397496, 'Red-Eyes Spirit', '真红眼之魂', 'レッドアイズ・スピリッツ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「真红眼」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(31733941, 'Red-Eyes Toon Dragon', '真红眼卡通龙', 'レッドアイズ・トゥーン・ドラゴン', 'Toon Monster', 'Dragon', 'DARK', 7, 2400, 2000, '①：这张卡在召唤·反转召唤·特殊召唤的回合不能攻击。 ②：自己场上有「卡通世界」存在，对方场上没有卡通怪兽存在的场合，这张卡可以直接攻击。 ③：1回合1次，自己主要阶段才能发动。从手卡把「真红眼卡通龙」以外的1只卡通怪兽无视召唤条件特殊召唤。'),
(45410988, 'Red-Eyes Transmigration', '真红眼转生', 'レッドアイズ・トランスマイグレーション', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「真红王」的降临必需。 ①：从自己的手卡·场上把等级合计直到8以上的怪兽解放或者作为解放的代替而把自己墓地的「真红眼」怪兽除外，从手卡把「真红王」仪式召唤。'),
(67300516, 'Red-Eyes Wyvern', '真红眼飞龙', '真紅眼の飛竜', 'Effect Monster', 'Dragon', 'WIND', 4, 1800, 1600, '这张卡的效果发动的回合，自己不能通常召唤。 ①：自己结束阶段把墓地的这张卡除外，以自己墓地1只「真红眼」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(5186893, 'Red-Eyes Zombie Dragon', '真红眼不死龙', '真紅眼の不死竜', 'Effect Monster', 'Zombie', 'DARK', 7, 2400, 2000, '这张卡可以把1只不死族怪兽解放攻击表示上级召唤。 ①：这张卡战斗破坏不死族怪兽送去墓地时才能发动。那只不死族怪兽在自己场上特殊召唤。'),
(38192988, 'Red-Eyes Zombie Dragon Lord', '真红眼不死龙皇', '真紅眼の不死竜皇', 'Synchro Monster', 'Zombie', 'DARK', 10, 2800, 2400, '不死族调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：对方回合，以「真红眼不死龙皇」以外的自己墓地1只不死族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡在墓地存在的场合，把自己场上1只不死族怪兽除外才能发动。这张卡特殊召唤。'),
(28240337, 'Red-Eyes Zombie Necro Dragon', '真红眼不死尸龙', '真紅眼の不屍竜', 'Synchro Monster', 'Zombie', 'DARK', 7, 2400, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力·守备力上升双方的场上·墓地的不死族怪兽数量×100。 ②：这张卡以外的不死族怪兽被战斗破坏时才能发动。选自己或者对方的墓地1只不死族怪兽在自己场上特殊召唤。'),
(30494314, 'Red-Headed Oni', '红血鬼', '紅血鬼', 'Effect Monster', 'Zombie', 'DARK', 4, 1700, 1000, '这张卡用不死族怪兽的效果从墓地的特殊召唤成功时，选择自己场上1只不死族怪兽才能发动。把场上1个超量素材取除，选择的怪兽的等级上升1星，攻击力上升300。'),
(68769900, 'Redbeard, the Plunder Patroll Matey', '海造贼-红胡子航海士', '海造賊－赤髭の航海士', 'Effect Monster', 'Fiend', 'WATER', 4, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：对方回合才能发动。把持有和对方的场上·墓地的怪兽的其中任意种相同属性的1只「海造贼」怪兽从额外卡组特殊召唤，自己场上的这张卡当作装备卡使用给那只怪兽装备。 ②：这张卡从手卡·怪兽区域送去墓地的场合，以「海造贼-红胡子航海士」以外的自己场上1只「海造贼」怪兽为对象才能发动。这张卡当作装备卡使用给那只怪兽装备。'),
(84404797, 'Redeemable Jar', '可回收瓶', 'リターナブル瓶', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：从自己墓地把1张陷阱卡除外才能发动。从自己墓地选原本卡名和那张卡不同的1张陷阱卡加入手卡。'),
(90411554, 'Redox, Dragon Ruler of Boulders', '岩征龙－石壑', '巌征竜－レドックス', 'Effect Monster', 'Dragon', 'EARTH', 7, 1600, 3000, '这个卡名的①～④的效果1回合只能有1次使用其中任意1个。 ①：从手卡把这张卡和1只地属性怪兽丢弃去墓地，以自己墓地1只怪兽为对象才能发动。那只特殊召唤。 ②：把2只龙族或地属性的怪兽从自己的手卡·墓地除外才能发动。这张卡从手卡·墓地特殊召唤。 ③：这张卡特殊召唤的场合，对方结束阶段发动。这张卡回到手卡。 ④：这张卡被除外的场合才能发动。从卡组把1只龙族·地属性怪兽加入手卡。'),
(71353388, 'Reed Butterfly', '领头蝴蝶', 'リード・バタフライ', 'Effect Monster', 'Insect', 'WIND', 1, 300, 600, '对方场上有同调怪兽表侧表示存在，自己场上没有同调怪兽表侧表示存在的场合，这张卡可以从手卡特殊召唤。'),
(30276969, 'Reese the Ice Mistress', '冰弹手 蕾丝', '氷弾使いレイス', 'Tuner Monster', 'Sea Serpent', 'WATER', 2, 800, 800, '①：这张卡不会被和4星以上的怪兽的战斗破坏。'),
(51023024, 'Reeshaddoll Wendi', '翼影依 温蒂', '影霊の翼 ウェンディ', 'Flip Effect Monster', 'Psychic', 'WIND', 3, 1500, 1000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合才能发动。从卡组把「影灵之翼 文蒂」以外的1只「影依」怪兽表侧守备表示或里侧守备表示特殊召唤。 ②：这张卡被效果送去墓地的场合才能发动。从卡组把「影灵之翼 文蒂」以外的1只「影依」怪兽里侧守备表示特殊召唤。'),
(8852158, 'Reeshaddoll Wendikurhu', '翼影依灵骑 温蒂玖琉布', '影霊翼騎 ウェンディクルフ', 'Fusion Monster', 'Psychic', 'WIND', 6, 200, 2800, '「影依」怪兽＋风属性怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：自己·对方回合可以发动。场上的里侧表示怪兽任意数量变成表侧守备表示。那之后，可以把最多有那之内的反转怪兽数量的除变成表侧守备表示的怪兽以外的表侧表示怪兽变成里侧守备表示。 ②：这张卡被送去墓地的场合，以自己墓地1张「影依」卡为对象才能发动。那张卡加入手卡。'),
(36331074, 'Reeze, Whirlwind of Gusto', '薰风的疾风 莉兹', 'ガスタの疾風 リーズ', 'Effect Monster', 'Psychic', 'WIND', 5, 1900, 1400, '让1张手卡回到卡组最下面，选择对方场上存在的1只怪兽和自己场上表侧表示存在的1只名字带有「薰风」的怪兽发动。选择的怪兽的控制权交换。这个效果1回合只能使用1次。'),
(2851070, 'Reflect Bounder', '魔镜导士反射弹回者', '魔鏡導士リフレクト・バウンダー', 'Effect Monster', 'Machine', 'LIGHT', 4, 1700, 1000, '场上表侧攻击表示存在的这张卡被对方怪兽攻击的场合，那次伤害计算前给与对方基本分攻击怪兽的攻击力数值的伤害，那次伤害计算后这张卡破坏。'),
(39000945, 'Reflection of Endymion', '恩底弥翁之女皇', 'エンプレス・オブ・エンディミオン', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 7, 1850, 2700, '自己对「恩底弥翁的皇后」1回合只能有1次特殊召唤。 ①：这张卡特殊召唤成功的场合，以自己场上1张其他的有魔力指示物放置的卡和对方场上1张卡为对象才能发动。那些自己以及对方的卡回到持有者手卡。那之后，从自己场上回到手卡的卡放置的数量的魔力指示物给这张卡放置。 ②：有魔力指示物放置的这张卡被战斗破坏时才能发动。从卡组把1张「恩底弥翁」卡加入手卡。'),
(64881644, 'Refrain the Melodious Songstress', '幻奏歌姬 露芙兰', '幻奏の歌姫ルフラン', 'Pendulum Effect Monster', 'Fairy', 'LIGHT', 4, 1600, 800, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「幻奏的歌姬 勒弗兰」以外的1只「幻奏」怪兽加入手卡。 ②：这张卡在额外卡组表侧存在的状态，自己场上有「幻奏」融合怪兽特殊召唤的场合才能发动。这张卡在自己的灵摆区域放置。'),
(70821187, 'Regenerating Mummy', '再生木乃伊', '再生ミイラ', 'Effect Monster', 'Zombie', 'DARK', 4, 1800, 1500, '对方控制的卡的效果把这张卡从手卡送去墓地时，这张卡回到手卡。'),
(31986288, 'Regenerating Rose', '分裂魔界蔷薇', 'スプリット・D・ローズ', 'Effect Monster', 'Plant', 'DARK', 7, NULL, 1500, '这张卡被战斗破坏送去墓地时，可以在自己场上把2只「魔界蔷薇衍生物」（植物族·暗·3星·攻/守1200）特殊召唤。'),
(31986289, 'Regenerating Rose Token', '分裂魔界蔷薇', 'スプリット・D・ローズ', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(31786838, 'Regenesis', '再世记', '再世記', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组选1只「再世」怪兽加入手卡或送去墓地。自己场上有「再世」怪兽存在的场合，也能作为代替把1只攻击力和守备力是2500的怪兽从卡组加入手卡。 ②：把这个回合没有送去墓地的这张卡从墓地除外，以自己墓地1只「再世」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(95718355, 'Regenesis Archfiend', '再世荒恶魔神 贝米德巴尔', '再世の魔神 ベミドバル', 'Effect Monster', 'Fiend', 'EARTH', 8, 2500, 2500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：这张卡可以把攻击力或守备力是2500的手卡1只其他怪兽给对方观看，从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。「再世之魔神 必密巴」以外的自己的卡组·除外状态的1张「再世」卡加入手卡。 ③：这张卡被送去墓地的对方回合的结束阶段才能发动。这张卡加入手卡。'),
(27781371, 'Regenesis Birth', '天地再世', '天地再世', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把1只「再世」怪兽送去墓地，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。 ②：对方回合，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。自己的手卡·墓地·除外状态的「再世」怪兽尽可能特殊召唤（同名卡最多1张）。这个效果特殊召唤的怪兽在结束阶段送去墓地。'),
(67171933, 'Regenesis Code', '再世神', '再世神', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「再世」怪兽特殊召唤。这个效果特殊召唤的怪兽在对方结束阶段送去墓地。这张卡的发动后，直到下个回合的结束时自己不能从额外卡组把怪兽特殊召唤。 ②：自己主要阶段，把这个回合没有送去墓地的这张卡从墓地除外，以自己的除外状态的1只「再世」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(95382988, 'Regenesis Commands', '再世十诫', '再世十戒', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：和自己场上的「再世」怪兽相同纵列的对方场上的全部卡受以下效果适用。 ●表侧表示卡：效果无效化。 ●里侧表示怪兽：不能把表示形式变更。 ●里侧表示的魔法·陷阱卡：直到下个回合的结束时不能发动。'),
(36672909, 'Regenesis Cycle', '再世律', '再世律', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有原本攻击力或原本守备力是2500的怪兽存在的场合，以对方场上1张卡为对象才能发动（自己场上有「创世之神 狄特罗诺米安」存在的场合，这个效果的对象可以变成2张）。那张卡除外。 ②：把这个回合没有送去墓地的这张卡从墓地除外才能发动。从手卡把1只攻击力或守备力是2500的怪兽特殊召唤。'),
(59323650, 'Regenesis Dragon', '再世呼召龙神 瓦库拉', '再世の龍神 ワイクラー', 'Effect Monster', 'Dragon', 'WIND', 8, 2500, 2500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：场上有原本攻击力或原本守备力是2500的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己·对方回合，把这张卡解放，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡除外。 ③：这张卡被送去墓地的对方回合的结束阶段才能发动。这张卡加入手卡。'),
(22812963, 'Regenesis Lord', '创言再世神 德乌特洛诺米翁', '創世の神 デウテロノミオン', 'Effect Monster', 'Illusion', 'LIGHT', 10, 2500, 2500, '这张卡不能通常召唤。「创世之神 狄特罗诺米安」1回合1次在把原本攻击力和原本守备力是2500的自己场上1只表侧表示怪兽除外的场合才能特殊召唤。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张「再世」魔法·陷阱卡在自己场上盖放。 ②：这张卡的攻击力在战斗阶段内上升2500。 ③：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(47082621, 'Regenesis Overlord', '葬语再世神 德瓦利姆', '葬世の神 デーヴァリーム', 'Effect Monster', 'Illusion', 'DARK', 10, 2500, 2500, '这张卡不能通常召唤。「葬世之神 德瓦里姆」1回合1次在把攻击力或守备力是2500的自己墓地2只怪兽除外的场合才能从墓地特殊召唤。 ①：这张卡特殊召唤的场合，以最多有攻击力或守备力是2500的自己的除外状态的怪兽数量的对方的场上·墓地的卡为对象才能发动。那些卡回到手卡。 ②：对方场上的怪兽的攻击力只在战斗阶段内下降2500。'),
(22938501, 'Regenesis Sage', '再世名讳导神 摄墨斯', '再世の導神 シェモース', 'Effect Monster', 'Spellcaster', 'WATER', 7, 2500, 2500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：场上有原本攻击力或原本守备力是2500的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：对方把卡的效果发动时，从自己的手卡·场上（表侧表示）把这张卡以外的1张「再世」卡送去墓地才能发动。那个发动无效并破坏。 ③：这张卡被送去墓地的对方回合的结束阶段才能发动。这张卡加入手卡。'),
(96540807, 'Regenesis Warrior', '再世原初战神 贝凌席特', '再世の戦神 ベレシート', 'Effect Monster', 'Warrior', 'FIRE', 7, 2500, 2500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：场上有原本攻击力或原本守备力是2500的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己·对方回合，把这张卡解放，以对方场上1只怪兽为对象才能发动。那只怪兽回到手卡。 ③：这张卡被送去墓地的对方回合的结束阶段才能发动。这张卡加入手卡。'),
(79544790, 'Regretful Rebirth', '悔恨苏生', 'リグレット・リボーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的怪兽被战斗破坏送去墓地时才能发动。那1只怪兽在自己场上表侧守备表示特殊召唤。这个效果特殊召唤的怪兽在自己的结束阶段时破坏。'),
(20210570, 'Regulus', '雷古勒斯', 'レグルス', 'Effect Monster', 'Beast', 'LIGHT', 4, 1700, 1000, '选择自己墓地存在的1张场地魔法卡发动。选择的卡回到卡组。这个效果1回合只能使用1次。'),
(61480937, 'Regulus the Fairy Beast', '妖精兽 雷格鲁斯', '妖精獣レグルス', 'Effect Monster', 'Beast', 'LIGHT', 4, 1700, 1000, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把有「古代妖精龙」的卡名记述的1张魔法·陷阱卡加入手卡。 ②：自己主要阶段才能发动。从手卡把1只兽族·植物族·天使族而4星以下的光属性怪兽守备表示特殊召唤。 ③：把墓地的这张卡除外，以自己墓地1张场地魔法卡为对象才能发动。那张卡回到卡组最下面。那之后，自己抽1张。'),
(96228804, 'Regulus, the Prince of Endymion', '恩底弥翁之圣月皇太子 雷格鲁斯', '聖月の皇太子レグルス', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1700, 1300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，把手卡1只其他的魔法师族怪兽给对方观看才能发动。自己失去给人观看的怪兽的等级×300基本分，这张卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。从卡组把有「圣月之皇太子 雷古勒斯」的卡名记述的1张魔法卡加入手卡。 ③：这张卡1回合只有1次不会被战斗破坏。'),
(60439482, 'Regulus'' Arrow', '雷格鲁斯之箭', 'レグルスの矢', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「圣月之皇太子 雷古勒斯」存在的场合，可以从以下效果选择1个发动。 ●把这个回合进行过战斗的对方场上1只怪兽破坏。 ●通常·速攻魔法卡发动时才能发动。那个效果无效。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地1只「圣月之皇太子 雷古勒斯」或者有那个卡名记述的怪兽为对象才能发动。那只怪兽特殊召唤。'),
(41406613, 'Reign-Beaux, Overking of Dark World', '暗黑界的魔神王 雷恩', '暗黒界の魔神王 レイン', 'Effect Monster', 'Fiend', 'DARK', 8, 3000, 1800, '①：这张卡可以让自己场上1只7星以下的「暗黑界」怪兽回到持有者手卡，从墓地特殊召唤。 ②：这张卡被效果从手卡丢弃去墓地的场合才能发动。从卡组把「暗黑界的魔神王 雷恩」以外的1只5星以上的「暗黑界」怪兽加入手卡。被对方的效果丢弃的场合，可以再从自己的卡组·墓地选1只4星以下的「暗黑界」怪兽在自己或者对方场上特殊召唤。'),
(99458769, 'Reign-Beaux, Overlord of Dark World', '暗黑界的魔神 雷恩', '暗黒界の魔神 レイン', 'Effect Monster', 'Fiend', 'DARK', 7, 2500, 1800, '①：这张卡被对方的效果从手卡丢弃去墓地的场合发动。这张卡特殊召唤。 ②：这张卡的①的效果特殊召唤成功的场合发动。从以下效果选1个适用。 ●对方场上的怪兽全部破坏。 ●对方场上的魔法·陷阱卡全部破坏。'),
(57499304, 'Reincarnation of the Seventh Emperors', '七皇转生', '七皇転生', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的「No.101」～「No.107」其中任意种的「No.」超量怪兽或者有那怪兽在作为超量素材中的超量怪兽进行战斗的伤害计算时才能发动。那只自己怪兽除外（把持有超量素材的怪兽除外的场合那些超量素材也全部除外）。这张卡发动的回合的结束阶段，除「No.」怪兽外的1只3阶以下的超量怪兽从额外卡组特殊召唤，给与对方那个原本攻击力数值的伤害。'),
(68663427, 'Reincarnation Unveiling Mail', '转世揭幕铠', 'リンカーネイト・アンヴェイル・メイル', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「铠装超量」卡使用。这个卡名的卡在1回合只能发动1张。 ①：这张卡装备的超量怪兽得到以下效果。 ●这张卡不会被战斗破坏。 ●这张卡进行过战斗的自己·对方回合才能发动1次。这张卡1张装备卡回到手卡。那之后，进行1只水属性超量怪兽的超量召唤。 ②：这张卡被送去墓地的回合的结束阶段才能发动。这张卡给自己场上1只超量怪兽装备。'),
(10118318, 'Reinforce Truth', '休战增援', 'トゥルース・リインフォース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能进行战斗阶段。 ①：从卡组把1只2星以下的战士族怪兽特殊召唤。'),
(71948047, 'REINFORCE!', '加固！', 'REINFORCE！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「救援ACE队」卡使用。这个卡名的②的效果1回合只能使用1次。 ①：以自己场上1只「救援ACE队」怪兽为对象才能发动。那只自己怪兽在这个回合攻击力·守备力上升1500，不受对方怪兽的效果影响，只有1次不会被战斗破坏。 ②：把墓地的这张卡除外，以自己墓地1张「救援ACE队」魔法卡为对象才能发动。那张卡在自己场上盖放。'),
(80102359, 'Reinforced Human Psychic Borg', '强化人类 赛克', '強化人類サイコ', 'Effect Monster', 'Psychic', 'EARTH', 4, 1500, 800, '把自己墓地存在的1只念动力族怪兽从游戏中除外发动。这张卡的攻击力上升500。这个效果1回合可以使用最多2次。'),
(11224934, 'Reinforced Space', '强化空间', '強化空間', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的全部超量怪兽的攻击力直到结束阶段时上升那怪兽的超量素材每1个300。'),
(32807846, 'Reinforcement of the Army', '增援', '増援', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只4星以下的战士族怪兽加入手卡。'),
(79371897, 'Reinforcement of the Army''s Troops', '增援部队', '増援部隊', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己的战士族怪兽进行战斗的攻击宣言时才能发动。从手卡把1只4星以下的战士族怪兽特殊召唤。'),
(17814387, 'Reinforcements', '援军', '援軍', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升500。'),
(78161960, 'Reject Reborn', '抗拒苏生', 'リジェクト・リボーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的直接攻击宣言时才能发动。战斗阶段结束。那之后，可以从自己墓地选调整和同调怪兽各1只特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(74845897, 'Rekindling', '真炎的爆发', '真炎の爆発', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己墓地把守备力200的炎属性怪兽尽可能特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段除外。'),
(61434639, 'Rekindling the Ashened', '灰灭的复燃', '灰滅の復燃', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：让「灰灭的复燃」以外的自己的墓地·除外状态的1张「灰灭」卡回到卡组最下面，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。'),
(42776960, 'Relay Soul', '魂之接力', '魂のリレー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡把1只怪兽特殊召唤。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，自己受到的全部伤害变成0。那只怪兽从场上离开时对方决斗胜利。'),
(85395151, 'Release Brainwashing', '洗脑解放', '洗脳解放', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：手卡·场上的怪兽被解放的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽的原本持有者对应的以下效果适用。 ●自己：得到作为对象的怪兽的控制权。这个效果得到控制权的怪兽在结束阶段回到手卡。 ●对方：作为对象的怪兽的效果直到回合结束时无效。'),
(26956670, 'Release from Stone', '化石岩之解放', '化石岩の解放', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择1只被除外的自己的岩石族怪兽在自己场上特殊召唤。这张卡从场上离开时，那只怪兽破坏。那只怪兽破坏时这张卡破坏。'),
(75417459, 'Release Restraint', '拘束解除', '拘束解除', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只「铁骑士 基亚·弗里德」解放才能发动。从手卡·卡组把1只「剑圣-赤膊的基亚·弗里德」特殊召唤。'),
(98847704, 'Release Restraint Wave', '拘束解放波', '拘束解放波', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1张装备魔法卡发动。选择的装备魔法卡和对方场上盖放的魔法·陷阱卡全部破坏。'),
(38777931, 'Release, Reverse, Burst', '解放埋伏爆发', 'リリース・リバース・バースト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只名字带有「希望皇 霍普」的怪兽解放才能发动。对方场上盖放的魔法·陷阱卡全部破坏。'),
(37507488, 'Relieve Monster', '怪兽调换', 'モンスターレリーフ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。自己场上存在的1只怪兽回到手卡，那之后从手卡把1只4星怪兽特殊召唤。'),
(50185950, 'Relinkuriboh', '纳祭库里波', 'サクリボー', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '①：这张卡被解放的场合发动。自己从卡组抽1张。 ②：自己怪兽被战斗破坏的场合，可以作为代替把墓地的这张卡除外。'),
(64631466, 'Relinquished', '纳祭魔', 'サクリファイス', 'Ritual Effect Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '「幻想的仪式」降临。 ①：1回合1次，以对方场上1只怪兽为对象才能发动。那只对方怪兽当作装备卡使用给这张卡装备（只有1只可以装备）。 ②：这张卡的攻击力·守备力变成这张卡的效果装备的怪兽的各自数值，这张卡被战斗破坏的场合，作为代替把装备的那只怪兽破坏。 ③：用这张卡的效果把怪兽装备的这张卡的战斗让自己受到战斗伤害时，对方也受到相同数值的效果伤害。'),
(94259633, 'Relinquished Anima', '纳祭魔・阿尼玛', 'サクリファイス・アニマ', 'Link Monster', 'Spellcaster', 'DARK', NULL, NULL, NULL, '衍生物以外的1星怪兽1只 这个卡名的①的效果1回合只能使用1次。 ①：以这张卡所连接区1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽当作装备魔法卡使用给这张卡装备（只有1只可以装备）。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力数值。'),
(78063197, 'Relinquished Fusion', '纳祭魔结合', 'サクリファイス・フュージョン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的手卡·场上·墓地的怪兽作为融合素材除外，把1只「眼纳祭神」融合怪兽融合召唤。 ②：自己主要阶段把墓地的这张卡除外，以对方场上1只效果怪兽为对象才能发动。选自己场上1只「眼纳祭神」融合怪兽或「纳祭之魔」把作为对象的对方的效果怪兽当作那个效果的装备魔法卡使用来装备。'),
(54248491, 'Relinquished Spider', '牲祭蜘蛛', 'サクリファイス・スパイダー', 'Effect Monster', 'Insect', 'EARTH', 2, 300, 500, '自己墓地昆虫族怪兽有4只以上存在的场合，把这张卡解放发动。对方场上表侧守备表示存在的怪兽全部破坏。'),
(22589918, 'Reload', '上膛', 'リロード', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '将自己的全部手卡放回卡组。那之后，抽与放回卡组的卡数量相同的卡。'),
(54658815, 'Remote Rebirth', '远程苏生', 'リモート・リボーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方墓地1只怪兽为对象才能发动。那只怪兽在作为自己场上的连接怪兽所连接区的对方的主要怪兽区域特殊召唤。'),
(61656650, 'Remote Revenge', '悲剧的引爆器', '悲劇の引き金', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的怪兽成为持有（把场上1只怪兽破坏的效果）的魔法·陷阱·效果怪兽的效果的对象时才能发动。那个效果的对象移向对方场上存在的1只能变成正确对象的怪兽。'),
(94739788, 'Remove Brainwashing', '洗脑解除', '洗脳解除', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，自己与对方场上存在的所有怪兽的控制权回归原本持有者。'),
(51482758, 'Remove Trap', '陷阱拆除', '罠はずし', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '破坏表侧表示的场上的存在的1张陷阱卡。'),
(81306186, 'Renewal of the World', '世界回归', 'リターン・オブ・ザ・ワールド', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：作为这张卡的发动时的效果处理，从卡组把1只仪式怪兽除外。 ②：可以把这张卡送去墓地，从以下效果选择1个发动。 ●直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上1只怪兽解放或者作为解放的代替而让自己墓地1只仪式怪兽回到卡组，把这张卡的①的效果除外的怪兽仪式召唤。 ●这张卡的效果除外的怪兽加入手卡。'),
(60606759, 'Renge, Gatekeeper of Dark World', '暗黑界的番兵 兰治', '暗黒界の番兵 レンジ', 'Normal Monster', 'Fiend', 'DARK', 4, 100, 2100, '以暗黑界第一结实的身体著称，作为「铁壁兰治」被暗黑界的人们另眼相看。他的防守很少有突破者。'),
(8173184, 'Repair Genex Controller', '修复次代机・控制者', 'リペア・ジェネクス・コントローラー', 'Link Monster', 'Machine', 'DARK', NULL, 1200, NULL, '4星以下的「次世代」怪兽1只 自己对「修复次世代控制员」1回合只能有1次特殊召唤。 ①：这张卡连接召唤的场合才能发动。从自己墓地把1只「次世代」怪兽加入手卡。 ②：「次世代」怪兽用抽卡以外的方法加入自己手卡的场合才能发动（同一连锁上最多1次）。进行1只「次世代」怪兽的召唤。这个回合，自己不用以「次世代」调整为同调素材的同调召唤不能从额外卡组把怪兽特殊召唤。'),
(1665819, 'Replicard LAD', '复制龙 LAD', 'レプリカルド・ラッド', 'Effect Monster', 'Cyberse', 'DARK', 7, 2500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，从手卡把1只其他的7星以上的怪兽除外才能发动。这张卡特殊召唤。 ②：以自己场上1只表侧表示怪兽为对象才能发动。和那只怪兽是卡名不同并是等级·攻击力·守备力之内有2个以上相同的1只怪兽从卡组特殊召唤。这个效果特殊召唤的怪兽在这个回合不能把效果发动。'),
(34989413, 'Reprodocus', '重编梁龙', 'リプロドクス', 'Link Monster', 'Dinosaur', 'EARTH', NULL, 800, NULL, '怪兽2只 这个卡名的效果1回合只能使用1次。 ①：可以从以下效果选择1个发动。 ●宣言1个种族才能发动。这张卡所连接区的全部表侧表示怪兽的种族直到回合结束时变成宣言的种族。 ●宣言1个属性才能发动。这张卡所连接区的全部表侧表示怪兽的属性直到回合结束时变成宣言的属性。'),
(81782101, 'Reptia Egg', '爬虫蛋', 'レプティア・エッグ', 'Effect Monster', 'Reptile', 'EARTH', 1, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡不会被战斗破坏。 ②：这张卡召唤成功的场合，下次的自己回合的准备阶段，把这张卡解放才能发动。从手卡·卡组把最多3只4星以下的爬虫类族·岩石族怪兽特殊召唤（2只以上特殊召唤的场合必须全部是同名怪兽）。这个效果特殊召唤的怪兽在结束阶段除外。'),
(89594399, 'Reptilianne Coatl', '爬虫妖・科亚特尔', 'レプティレス・コアトル', 'Tuner Monster', 'Reptile', 'DARK', 4, 1400, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有爬虫类族·暗属性怪兽存在的场合才能发动。这张卡从手卡特殊召唤。对方场上有攻击力0的怪兽存在的场合，可以再把最多有那个数量的「爬虫妖」怪兽从手卡特殊召唤。 ②：把自己场上的这张卡作为爬虫类族同调怪兽的同调素材的场合，可以把这张卡当作调整以外的怪兽使用。'),
(8602351, 'Reptilianne Echidna', '爬虫妖・厄克德娜', 'レプティレス・エキドゥーナ', 'Link Monster', 'Reptile', 'DARK', NULL, 200, NULL, '包含爬虫类族怪兽的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0。 ②：自己主要阶段才能发动。把最多有对方场上的攻击力0的怪兽数量的爬虫类族怪兽从卡组加入手卡（同名卡最多1张）。这个效果的发动后，直到回合结束时自己不是爬虫类族怪兽不能从额外卡组特殊召唤。'),
(43002864, 'Reptilianne Gardna', '爬虫妖・守卫', 'レプティレス・ガードナー', 'Effect Monster', 'Reptile', 'WATER', 4, NULL, 2000, '自己场上存在的这张卡被破坏送去墓地时，从自己卡组把1只名字带有「爬虫妖」的怪兽加入手卡。'),
(43426903, 'Reptilianne Gorgon', '爬虫妖女·戈耳工', 'レプティレス・ゴルゴーン', 'Effect Monster', 'Reptile', 'DARK', 3, 1400, 1400, '这张卡进行攻击的伤害计算后，和这张卡进行战斗的怪兽攻击力变成0，变成不能把表示形式改变。'),
(60634565, 'Reptilianne Hydra', '爬虫妖・拉弥亚', 'レプティレス・ラミア', 'Synchro Monster', 'Reptile', 'DARK', 6, 2100, 1500, '「爬虫妖」调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤成功的场合发动。对方场上的攻击力0的怪兽全部破坏，自己从卡组抽出破坏的数量。'),
(57647597, 'Reptilianne Lamia', '爬虫妖・海德拉', 'レプティレス・ヒュドラ', 'Tuner Monster', 'Reptile', 'DARK', 2, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡在手卡存在，自己场上的怪兽只有爬虫类族怪兽的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0，这张卡特殊召唤。那之后，自己受到那只怪兽的原本攻击力数值的伤害。 ②：这张卡作为同调素材送去墓地的场合，以场上最多2只表侧表示怪兽为对象才能发动。那些怪兽的攻击力变成0。'),
(89810518, 'Reptilianne Medusa', '爬虫妖女·美杜莎', 'レプティレス・メデューサ', 'Effect Monster', 'Reptile', 'DARK', 6, 2200, 800, '把1张手卡送去墓地，选择对方场上表侧表示存在的1只怪兽发动。选择怪兽攻击力变成0，变成不能把表示形式改变。'),
(32138660, 'Reptilianne Melusine', '爬虫妖・美露莘', 'レプティレス・メルジーヌ', 'Synchro Monster', 'Reptile', 'DARK', 8, 2500, 2800, '爬虫类族调整＋调整以外的怪兽1只以上 这张卡的②的效果在同一连锁上只能发动1次。 ①：只用爬虫类族怪兽为素材作同调召唤的这张卡不会被战斗·效果破坏。 ②：对方把怪兽的效果发动时，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0。 ③：同调召唤的这张卡被对方送去墓地的场合才能发动。从卡组把1只爬虫类族怪兽加入手卡。'),
(79491903, 'Reptilianne Naga', '爬虫妖・那伽', 'レプティレス・ナージャ', 'Effect Monster', 'Reptile', 'DARK', 1, NULL, NULL, '①：这张卡不会被战斗破坏。 ②：这张卡和怪兽进行战斗的战斗阶段结束时发动。那些怪兽的攻击力变成0。 ③：这张卡守备表示存在的场合，自己结束阶段发动。表侧守备表示的这张卡变成表侧攻击表示。'),
(42090294, 'Reptilianne Nyami', '爬虫妖・尼亚米尼', 'レプティレス・ニャミニ', 'Effect Monster', 'Reptile', 'DARK', 2, 200, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己墓地有爬虫类族怪兽存在的场合，自己·对方的主要阶段，把这张卡从手卡送去墓地，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0。 ②：对方场上有攻击力0的怪兽存在的场合才能发动。这张卡从墓地特殊召唤。'),
(90576781, 'Reptilianne Poison', '爬虫妖毒', 'レプティレス・ポイズン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「爬虫妖」的怪兽表侧表示存在的场合才能发动。对方场上守备表示存在的1只怪兽变更为表侧攻击表示，那只怪兽的攻击力变成0。'),
(91580102, 'Reptilianne Rage', '爬虫妖怒', 'レプティレス・アンガー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽变成爬虫类族，攻击力上升800。此外，这张卡被破坏送去墓地时，选择对方场上表侧表示存在的1只怪兽。那只怪兽的攻击力下降800。'),
(81615450, 'Reptilianne Ramifications', '爬虫妖分歧', 'レプティレス・ラミフィケーション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以把1张手卡送去墓地，从以下效果选择2个发动。 ●从卡组把1只「爬虫妖」怪兽加入手卡。 ●从卡组把「爬虫妖女的蛇化分歧」以外的1张「爬虫妖」魔法·陷阱卡加入手卡。 ●选对方场上1只怪兽，那个攻击力变成0。'),
(17000165, 'Reptilianne Recoil', '爬虫妖反冲', 'レプティレス・リコイル', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只攻击力0的怪兽和自己墓地1只爬虫类族·暗属性怪兽为对象才能发动。那只场上的怪兽破坏，那只墓地的怪兽特殊召唤。 ②：对方把怪兽的效果发动的场合，以对方场上1只攻击力0的怪兽为对象才能发动。得到那只怪兽的控制权。那之后，在对方场上把1只「爬虫妖衍生物」（爬虫类族·地·1星·攻/守0）特殊召唤。'),
(16909657, 'Reptilianne Scylla', '爬虫妖女·斯库拉', 'レプティレス・スキュラ', 'Effect Monster', 'Reptile', 'DARK', 4, 1800, 1200, '这张卡战斗破坏攻击力0的怪兽的场合，可以把那只怪兽从墓地在自己场上表侧守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(16008155, 'Reptilianne Servant', '爬虫妖女使魔', 'レプティレス・サーヴァント', 'Effect Monster', 'Reptile', 'DARK', 1, 100, 100, '场上有这张卡以外的怪兽表侧表示存在的场合，这张卡破坏。这张卡成为魔法·陷阱卡的效果的对象时，这张卡破坏。只要这张卡在场上表侧表示存在，双方不能把怪兽召唤。'),
(21179143, 'Reptilianne Spawn', '爬虫妖产卵', 'レプティレス・スポーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己墓地存在的1只名字带有「爬虫妖」的怪兽从游戏中除外发动。在自己场上把2只「爬虫妖衍生物」（爬虫类族·地·1星·攻/守0）特殊召唤。'),
(21179144, 'Reptilianne Token', '爬虫妖产卵', 'レプティレス・スポーン', 'Token', 'Reptile', NULL, NULL, NULL, NULL, NULL),
(16886617, 'Reptilianne Vaskii', '爬虫妖・婆苏吉', 'レプティレス・ヴァースキ', 'Effect Monster', 'Reptile', 'DARK', 8, 2600, NULL, '这张卡不能通常召唤。把自己·对方场上2只攻击力0的怪兽解放的场合才能特殊召唤。 ①：「爬虫妖女·和修吉」在场上只能有1只表侧表示存在。 ②：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。那只对方的表侧表示怪兽破坏。'),
(42303365, 'Reptilianne Viper', '爬虫妖・毒蛇', 'レプティレス・バイパー', 'Tuner Monster', 'Reptile', 'DARK', 2, NULL, NULL, '①：这张卡召唤成功时，以对方场上1只攻击力0的怪兽为对象才能发动。得到那只攻击力0的怪兽的控制权。'),
(14878871, 'Rescue Cat', '救援猫', 'レスキューキャット', 'Effect Monster', 'Beast', 'EARTH', 4, 300, 100, '这个卡名的效果1回合只能使用1次。 ①：把场上的这张卡送去墓地才能发动。从卡组把2只3星以下的兽族怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。'),
(56343672, 'Rescue Ferret', '救援貂', 'レスキューフェレット', 'Effect Monster', 'Beast', 'EARTH', 4, 300, 100, '这个卡名的效果1回合只能使用1次。 ①：让场上的这张卡回到持有者卡组才能发动。等级合计直到变成6星为止从卡组选「救援雪貂」以外的怪兽任意数量在作为连接怪兽所连接区的自己场上特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。'),
(50485594, 'Rescue Hamster', '救援鼠', 'レスキューラット', 'Pendulum Effect Monster', 'Beast', 'EARTH', 4, 300, 100, '①：这张卡召唤成功的回合，自己的额外卡组有表侧表示的5星以下的灵摆怪兽存在的场合，把这张卡解放才能发动。从自己的额外卡组选1只表侧表示的5星以下的灵摆怪兽，从卡组把那2只同名怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。'),
(99742859, 'Rescue Hedgehog', '救援刺猬', 'レスキューヘッジホッグ', 'Effect Monster', 'Beast', 'EARTH', 4, 300, 100, '这个卡名的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。3星以下而种族·属性·等级相同的通常怪兽和效果怪兽各1只从卡组特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。'),
(63009228, 'Rescue Interlacer', '救援隔行人', 'レスキュー・インターレーサー', 'Effect Monster', 'Cyberse', 'LIGHT', 3, 1000, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：自己的电子界族怪兽被攻击的伤害计算时把这张卡从手卡丢弃才能发动。那次战斗发生的对自己的战斗伤害变成0。 ②：这张卡为这张卡的效果发动而被丢弃去墓地的回合的结束阶段发动。这张卡特殊召唤。'),
(85138716, 'Rescue Rabbit', '救援兔', 'レスキューラビット', 'Effect Monster', 'Beast', 'EARTH', 4, 300, 100, '这张卡不能从卡组特殊召唤。这个卡名的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。从卡组把2只4星以下的同名通常怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(70630741, 'Rescue Warrior', '救援战士', 'レスキュー・ウォリアー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1600, 1700, '这张卡的战斗发生的对自己的战斗伤害变成0。这张卡被战斗破坏的场合，选择对方场上表侧表示存在的1只原本持有者是自己的怪兽得到控制权。');